7: function getBizType(bizno) {
8:   const clean = bizno.replace(/[^0-9]/g, '');
9:   if (clean.length !== 10) return 'UNKNOWN';
10:   const mid = clean.substring(3, 5);
11:   const midNum = Number(mid);
12:   if ((midNum >= 1 && midNum <= 79) || (midNum >= 90 && midNum <= 99)) return '개인사업자';
13:   if (['81', '86', '87', '88'].includes(mid)) return '영리법인본점';
14:   if (mid === '85') return '영리법인지점';
15:   if (mid === '82') return '비영리법인';
16:   if (mid === '33') return '사내근로복지기금/단체';
17:   return '기타';
18: }
19: 
20: function isValidCorpNo(corpNo) {
21:   if (!corpNo) return false;
22:   const clean = corpNo.replace(/[^0-9]/g, '');
23:   if (clean.length !== 13) return false;
24:   const weights = [1, 2, 1, 2, 1, 2, 1, 2, 1, 2, 1, 2];
25:   let sum = 0;
26:   for (let i = 0; i < 12; i++) {
27:     sum += Number(clean[i]) * weights[i];
28:   }
29:   const remainder = sum % 10;
30:   const checkDigit = (10 - remainder) % 10;
31:   return Number(clean[12]) === checkDigit;
32: }
33: 
34: const audit = lines.map((l, idx) => {
35:   const p = l.split('\t');
36:   const company = (p[2] || '').trim();
37:   const bizno = (p[3] || '').trim();
38:   const corpNo = (p[13] || '').trim();
39:   const bizType = getBizType(bizno);
40:   const isCorpEntity = ['영리법인본점', '영리법인지점', '비영리법인'].includes(bizType) || company.includes('(주)') || company.includes('주식회사') || company.includes('㈜');
41:   
42:   return {
43:     no: idx + 1,
